def index_on_inner_list(list_data, index_no):
    """Write a function to sort a list of lists by a given index of the inner list."""
    return sorted(list_data, key=lambda inner: inner[index_no])
", "tests/test_solution.py": "import solution
from solution import index_on_inner_list


def test_module_imports():
    assert solution is not None


def test_example_index_0():
    data = [('Greyson Fulton', 98, 99), ('Brady Kent', 97, 96), ('Wyatt Knott', 91, 94), ('Beau Turnbull', 94, 98)]
    assert index_on_inner_list(data, 0) == [('Beau Turnbull', 94, 98), ('Brady Kent', 97, 96), ('Greyson Fulton', 98, 99), ('Wyatt Knott', 91, 94)]


def test_sort_by_numeric_index():
    data = [('Greyson Fulton', 98, 99), ('Brady Kent', 97, 96), ('Wyatt Knott', 91, 94), ('Beau Turnbull', 94, 98)]
    assert index_on_inner_list(data, 1) == [('Wyatt Knott', 91, 94), ('Beau Turnbull', 94, 98), ('Brady Kent', 97, 96), ('Greyson Fulton', 98, 99)]
    assert index_on_inner_list(data, 2) == [('Wyatt Knott', 91, 94), ('Brady Kent', 97, 96), ('Beau Turnbull', 94, 98), ('Greyson Fulton', 98, 99)]


def test_list_of_lists():
    assert index_on_inner_list([[3, 'c'], [1, 'a'], [2, 'b']], 0) == [[1, 'a'], [2, 'b'], [3, 'c']]
    assert index_on_inner_list([[3, 'c'], [1, 'a'], [2, 'b']], 1) == [[1, 'a'], [2, 'b'], [3, 'c']]


def test_empty_single_and_negative_index():
    assert index_on_inner_list([], 0) == []
    assert index_on_inner_list([[2, 1]], 0) == [[2, 1]]
    assert index_on_inner_list([[1, 30], [2, 10], [3, 20]], -1) == [[2, 10], [3, 20], [1, 30]]


def test_does_not_mutate_input():
    data = [[3, 'c'], [1, 'a'], [2, 'b']]
    original = list(data)
    index_on_inner_list(data, 0)
    assert data == original
